<?php
/** TEMP PS S1677 run f — petshop-feeds v2.5.0 DEPLOY (D: kainos grindys 'pigu' <€12) + Google feed regeneracija ir 'pigu' statistika (G). */
add_action('init', function(){
  if (!isset($_GET['ps_s1677f'])) return; global $wpdb; $p=$wpdb->prefix; $F=$_GET['ps_s1677f']; $o=array('v'=>'S1677 f','faze'=>$F);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $bk=wp_upload_dir()['basedir'].'/ps-backups/'; $f1=function_exists('ps_feeds_generuoti')?(new ReflectionFunction('ps_feeds_generuoti'))->getFileName():WPMU_PLUGIN_DIR.'/petshop-feeds.php'; $o['kelias']=$f1;
  if($F==='D'){
    $k1=base64_decode('');
    $gyvas=file_get_contents($f1);
    if(strpos($gyvas,"PS_FEEDS_VERSIJA', '2.4.1'")===false){ $o['STOP']='gyvas ne 2.4.1: '.md5($gyvas); }
    elseif(md5($k1)!=='97626f5e92bdb4439164f0b97761f4b5'){ $o['STOP']='b64 md5'; }
    elseif(@token_get_all($k1,TOKEN_PARSE)===false){ $o['STOP']='sintaksė'; }
    else { copy($f1,$bk.'petshop-feeds.php.bak_s1677'); file_put_contents($f1,$k1); $o['md5']=md5_file($f1);
      $r=wp_remote_get(home_url('/?ps_ping_s1677f='.time()),array('timeout'=>25,'sslverify'=>false)); $c=is_wp_error($r)?'ERR':wp_remote_retrieve_response_code($r); $o['ping']=$c;
      if(is_wp_error($r)||$c>=500){ copy($bk.'petshop-feeds.php.bak_s1677',$f1); $o['ROLLBACK']=1; } }
  }
  if($F==='G'){
    $o['versija']=defined('PS_FEEDS_VERSIJA')?PS_FEEDS_VERSIJA:'?'; $o['taisykles']=ps_feeds_google_taisykles();
    $o['gen']=ps_feeds_generuoti(array('google'));
    $x=file_get_contents(ps_feeds_kelias('google')); $o['baitai']=strlen($x);
    preg_match_all('#<g:custom_label_1>([^<]*)</g:custom_label_1>#',$x,$m); $o['label1']=array_count_values($m[1]);
    preg_match_all('#<g:custom_label_0>([^<]*)</g:custom_label_0>#',$x,$m); $o['label0']=array_count_values($m[1]);
    preg_match_all('#<g:custom_label_1>pigu</g:custom_label_1>#',$x,$m); $o['pigu_n']=count($m[0]); $o['items']=substr_count($x,'<item>');
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
